  background-color: transparent !important;
  background-image: var(--header-avatar-img) !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  box-shadow: none !important;
  border: none !important;
  outline: none !important;
  transform: translateY(0px) !important; /* ❎ 右侧大头像上下位置：0px 越大越往下，负数越往上 */
  flex-shrink: 0 !important;
  cursor: pointer !important;
}

/* 隐藏原本 info 键自带的图标 */
#chat-detail-screen .header-btn-info svg {
  display: none !important;
}

/* ==========================================================================
   第二部分：底部 (Footer)
   ========================================================================== */

/* 底栏外层大背景：与全局主背景色同步贯通 */
.input-area-custom,
div:has(> .input-row-wrapper) {
  background: var(--custom-input-bg) !important;
