/* =================================== */
/* 🌟 时间戳与拍一拍胶囊 */
/* =================================== */
:root {
  --sys-msg-bg: rgba(239, 239, 239, 0.85);
  --sys-msg-bg-f9: rgba(249,249,249,.7);
  --sys-msg-color: #888888;
  --sys-msg-radius: 5px;
  --sys-msg-padding: 4px 8px;
  --timestamp-padding: 2px 4px;
  --sys-msg-font-size: 12px;
  --sys-msg-backdrop: blur(10px) saturate(180%);
  --sys-msg-border: 1px solid rgba(0,0,0,.06);
}
@media (prefers-color-scheme: dark) {
  body {
    --sys-msg-bg: rgba(37, 37, 37, 0.85);
    --sys-msg-bg-f9: rgba(37, 37, 37, 0.85);
    --sys-msg-color: #999999;
    --sys-msg-border: 1px solid #272727;
  }
}
.timestamp-custom,
.date-divider-custom {
  display: block !important;
  width: fit-content !important;
  margin: 12px auto !important;
  padding: var(--timestamp-padding) !important;
  background: var(--sys-msg-bg-f9) !important;
  color: var(--sys-msg-color) !important;
  border-radius: var(--sys-msg-radius) !important;
  font-size: var(--sys-msg-font-size) !important;
  font-weight: 500 !important;
  backdrop-filter: var(--sys-msg-backdrop) !important;
  -webkit-backdrop-filter: var(--sys-msg-backdrop) !important;
  border: var(--sys-msg-border) !important;
  box-shadow: none !important;
}
.msg-narration-custom {
  display: block !important;
  width: fit-content !important;
  max-width: calc(100% - 64px) !important;
  box-sizing: border-box !important;
  margin: var(--narration-margin) !important;
  padding: var(--narration-padding) !important;
  background: var(--narration-bg) !important;
  color: var(--narration-color) !important;
  border: var(--narration-border) !important;
  border-radius: var(--narration-radius) !important;
  font-size: var(--narration-size) !important;
  letter-spacing: 1px !important;
  font-style: var(--narration-style) !important;
  backdrop-filter: var(--narration-backdrop) !important;
  -webkit-backdrop-filter: var(--narration-backdrop) !important;
  box-shadow: var(--narration-shadow) !important;
}
.nuo-pat-msg {
  display: block !important;
  width: fit-content !important;
  margin: 12px auto !important;
  padding: var(--sys-msg-padding) !important;
  background: var(--sys-msg-bg-f9) !important;
  color: var(--sys-msg-color) !important;
  border-radius: var(--sys-msg-radius) !important;
  font-size: var(--sys-msg-font-size) !important;
  backdrop-filter: var(--sys-msg-backdrop) !important;
  -webkit-backdrop-filter: var(--sys-msg-backdrop) !important;
  border: var(--sys-msg-border) !important;
  box-shadow: none !important;
  font-style: normal !important;
}

/* =================================== */
/* 🌟 翻译微信化 */
/* =================================== */
.msg-translation-detached {
  display: block !important;
  margin-top: 5px !important;
  width: fit-content !important;
  max-width: 72vw !important;
}
.msg-translation-content {
  display: none !important;
}
.msg-translation-detached-content {
  background: #FFFFFF !important;
  color: #000000 !important;
  border-radius: 5px !important;
  padding: 10px 12px !important;
  font-size: 14px !important;
  line-height: 1.5 !important;
  box-shadow: none !important;
  word-wrap: break-word !important;
  word-break: break-all !important;
}
@media (prefers-color-scheme: dark) {
  body .msg-translation-detached-content {
    background: #2C2C2C !important;
    color: #FFFFFF !important;
    border: 1px solid none !important;
  }
}
.msg-translation-wrapper {
  position: absolute !important;
  top: 0 !important;
  right: 0 !important;
  width: 45px !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
}
.msg-translation-btn {
  width: 100% !important;
  height: 100% !important;
  opacity: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}
.bubble-me-custom,
.bubble-them-custom {
  position: relative !important;
}

/* 🌟 翻译小尾巴 */
.msg-translation-detached-content {
  padding-bottom: 25px !important;
  position: relative !important;
}
.msg-translation-detached-content::after {
  content: "由微信提供翻译支持";
  position: absolute !important;
  left: 28px !important;
  bottom: 10px !important;
  font-size: 11px !important;
  color: #b2b2b2 !important;
  line-height: 12px !important;
  pointer-events: none !important;
}
.msg-translation-detached-content::before {
  content: "";
  position: absolute !important;
  left: 12px !important;
  bottom: 10px !important;
  width: 12px !important;
  height: 12px !important;
  background-color: #c9c9c9 !important;
  border-radius: 50% !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" stroke="%23F5F5F5" stroke-linecap="round"><line x1="6" y1="13" x2="10" y2="17" stroke-width="2.5"/><line x1="10" y1="17" x2="18" y2="8" stroke-width="1.5"/></svg>') !important;
  background-size: 12px 12px !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  pointer-events: none !important;
}
/* 给独立翻译气泡加个“保底宽度”，防止短句把底部小字挤换行 */
.msg-translation-detached,
.msg-translation-detached-content {
  min-width: 140px !important;
}

/* 顺手给底部小字加个不换行保护 */
.msg-translation-detached-content::after {
  white-space: nowrap !important;
}
@media (prefers-color-scheme: dark) {
  body .msg-translation-detached-content::after {
    color: #8e8e93 !important;
  }
  body .msg-translation-detached-content::before {
    background-color: #bcbcbc !important;
  }
}

