/* =========================================================
   v2.3 最终修正：彻底移除名片横线 + 夜间小角同步变暗
   ========================================================= */
.cc-card,
.cc-card .cc-top,
.cc-card .cc-avatar,
.cc-card .cc-avatar img,
.cc-card img.cc-avatar,
.cc-card .cc-name,
.cc-card .cc-sign,
.cc-card .cc-foot,
.cc-card .cc-added,
.cc-card .cc-add-btn {
  border-top: 0 !important;
  border-bottom: 0 !important;
  box-shadow: none !important;
  outline: none !important;
}

/* 分隔线可能来自原组件的 hr、分割元素或伪元素 */
.cc-card hr,
.cc-card [role="separator"],
.cc-card [class~="divider"],
.cc-card [class~="separator"],
.cc-card [class*="divider"],
.cc-card [class*="separator"],
.cc-card::before,
.cc-card .cc-top::before,
.cc-card .cc-top::after,
.cc-card .cc-avatar::before,
.cc-card .cc-avatar::after,
.cc-card .cc-foot::before,
.cc-card .cc-foot::after {
  display: none !important;
  content: none !important;
  height: 0 !important;
  min-height: 0 !important;
  border: 0 !important;
  background: none !important;
  box-shadow: none !important;
}

/* 小角直接读取卡片背景变量，避免根节点变量固定成白色 */
.cc-card::after {
  background: var(--cc-card-bg) !important;
  background-color: var(--cc-card-bg) !important;
  background-image: none !important;
  border: 0 !important;
  box-shadow: none !important;
}

/* 系统夜间模式 */
@media (prefers-color-scheme: dark) {
  body .cc-card::after {
    background: #2c2c2e !important;
    background-color: #2c2c2e !important;
  }
}

/* 应用内夜间模式开关优先同步小角颜色 */
body.dark-mode .cc-card::after {
  background: #2c2c2e !important;
  background-color: #2c2c2e !important;
}

/* =========================================================
   v2.4：压缩名片上下高度，并缩短头像与底部标签的距离
   ========================================================= */
.cc-card {
  min-height: 112px !important;
  padding-top: 10px !important;
  padding-bottom: 8px !important;
}
