  --sim-expand-offset: 50px;
  --sim-expand-top: 50%;
}

/* 日间模式：系统 light 且 App 没有手动开夜间开关 */
@media (prefers-color-scheme: light) {
  body:not(.dark-mode) {
    --sim-expand-bg: rgba(249,249,249,.7);
    --sim-expand-color: #191919;
  }
}

/* 夜间模式：系统 dark */
