  :root {
    --sim-expand-bg: #272728;
    --sim-expand-color: #939494;
  }
}

/* 夜间模式：App 内手动开关（兼容 body.dark-mode） */
body.dark-mode {
  --sim-expand-bg: #272728;
  --sim-expand-color: #939494;
}

/* 让内容栈成为定位参照 */
.msg-me .msg-content-stack:has(.msg-sim-card),
.msg-them .msg-content-stack:has(.msg-sim-card) {
  position: relative !important;
  overflow: visible !important;
}

/* 公共样式：对方用 ::after，我方用 ::before */
.msg-them .msg-content-stack:has(.msg-sim-card)::after,
.msg-me .msg-content-stack:has(.msg-sim-card)::before {
  content: "展开3" !important;
  position: absolute !important;
  top: var(--sim-expand-top) !important;
  transform: translateY(-50%) !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  height: var(--sim-expand-height) !important;
  padding: var(--sim-expand-padding) !important;
  box-sizing: border-box !important;
  border-radius: var(--sim-expand-radius) !important;

  background: var(--sim-expand-bg) !important;
  color: var(--sim-expand-color) !important;
  -webkit-text-fill-color: var(--sim-expand-color) !important;

  font-size: var(--sim-expand-font-size) !important;
  font-weight: var(--sim-expand-font-weight) !important;
  line-height: 1 !important;
  white-space: nowrap !important;

  border: none !important;
  box-shadow: none !important;
  z-index: 30 !important;
  pointer-events: none !important;
}

/* 对方：右侧 */
.msg-them .msg-content-stack:has(.msg-sim-card)::after {
  right: calc(-1 * var(--sim-expand-offset)) !important;
  left: auto !important;
}

/* 我方：左侧 */
.msg-me .msg-content-stack:has(.msg-sim-card)::before {
  left: calc(-1 * var(--sim-expand-offset)) !important;
  right: auto !important;
}
